// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 600, 900);

var W = 600, H = 900;
var tMax = 10;
var eqTime = 5;
var currentTime = 0;
var initialA = 1;
var graphMode = 'Concentration';
var draggingMarker = false;
var activeStep = 0;

var blue = '#4f6db7';
var red = '#e62525';
var redOrange = '#c54b2c';
var gray = '#808285';
var paleYellow = '#f6edcc';

var demoSteps = [
  {
    title: 'Start with only N2O4',
    narration: 'At t = 0 the container contains only colorless N₂O₄, so [N₂O₄] is high and [NO₂] is essentially zero. The reverse rate is initially very small because little or no NO₂ is present.',
