  },
  {
    title: 'Approach equilibrium',
    narration: 'Drag the time marker to the middle of the graph. N₂O₄ is decomposing into brown NO₂, so [N₂O₄] falls, [NO₂] rises, and the vial color deepens.',
    state: { initialN2O4: 1, graphQuantity: 'Concentration' },
    time: 2.8
  },
  {
    title: 'See the rate criterion',
    narration: 'Switch to the rate graph and drag toward the dashed equilibrium line. The forward rate decreases while the reverse rate increases until the two curves meet.',
    state: { initialN2O4: 1, graphQuantity: 'Rate' },
    time: 4.7
  },
  {
    title: 'Equilibrium is dynamic',
    narration: 'After the dashed line, the two rates remain equal and constant. Molecules are still reacting in both directions, but the macroscopic concentrations no longer change.',
    state: { initialN2O4: 1, graphQuantity: 'Rate' },
    time: 7.2
  },
  {
    title: 'Change the starting amount',
    narration: 'Increase the initial N₂O₄ concentration. The curves, molecular counts, and final color update together, but the equilibrium condition remains the same: forward rate equals reverse rate.',
    state: { initialN2O4: 1.6, graphQuantity: 'Concentration' },
    time: 7.2
  }
];

function progressAt(t) {
  if (t >= eqTime) return 1;
  var tau = 1.65;
  var s = 1 - Math.exp(-t / tau);
  var sEq = 1 - Math.exp(-eqTime / tau);
  return Math.max(0, Math.min(1, s / sEq));
}

function stateAt(t) {
  var p = progressAt(t);
  var aEq = 0.32 * initialA;
  var bEq = 2 * (initialA - aEq);
  var A = initialA - (initialA - aEq) * p;
  var B = bEq * p;
  var rEq = 0.42 * initialA;
  var r0 = 1.0 * initialA;
  var rf = rEq + (r0 - rEq) * Math.pow(1 - p, 1.45);
  var rr = rEq * Math.pow(p, 1.35);
  if (t >= eqTime) {
    A = aEq;
    B = bEq;
    rf = rEq;
    rr = rEq;
  }
  return { p: p, A: A, B: B, rf: rf, rr: rr, aEq: aEq, bEq: bEq, rEq: rEq };
}

function addInteractivity(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
  return el;
}

function haloText(parent, txt, x, y, size, anchor) {
  var t = parent.text(txt).font({ family: 'Arial, sans-serif', size: size, anchor: anchor || 'middle' }).fill('#000');
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  t.center(x, y);
  return t;
}

function formulaText(parent, txt, x, y, size, anchor) {
  var t = parent.text(txt).font({ family: 'Arial, sans-serif', size: size, anchor: anchor || 'middle' }).fill('#000');
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  t.center(x, y);
  return t;
}

function drawArrow(parent, cx, y1, y2) {
  var pts = [
    [cx - 9, y1], [cx + 9, y1], [cx + 9, y2 - 32],
    [cx + 22, y2 - 32], [cx, y2], [cx - 22, y2 - 32],
    [cx - 9, y2 - 32]
  ];
  var p = parent.polygon(pts.map(function (q) { return q[0] + ',' + q[1]; }).join(' '))
    .fill('#fff').stroke({ color: '#111', width: 1.1, linejoin: 'round' });
  return addInteractivity(p, 'Gas sample enters the sealed container.', 'Molecular snapshot', 'Each container represents the same reacting system at a different time. The gas color darkens as more brown NO₂ is present.');
}

function drawTestTube(parent, cx, cy, color, op) {
  var g = parent.group();
  var tube = g.rect(26, 128).radius(13).center(cx, cy).fill({ color: color, opacity: op }).stroke({ color: '#c7c7d7', width: 1.2 });
  g.line(cx - 8, cy - 51, cx - 8, cy + 50).stroke({ color: '#fff', width: 3, opacity: 0.38, linecap: 'round' });
  g.ellipse(26, 10).center(cx, cy + 64).fill({ color: color, opacity: op }).stroke({ color: '#c7c7d7', width: 0.8 });
  g.rotate(-32, cx, cy);
  addInteractivity(tube, 'Vial color reflects the amount of NO₂.', 'Color cue', 'N₂O₄ is nearly colorless, while NO₂ is brown. As the equilibrium mixture develops, the gas becomes orange-brown rather than colorless.');
  return g;
}

function drawNO2(parent, x, y, s, rot) {
  var g = parent.group();
  g.line(0, 0, -0.8 * s, -0.95 * s).stroke({ color: '#777', width: 1.4, linecap: 'round' });
  g.line(0, 0, 0.9 * s, 0.65 * s).stroke({ color: '#777', width: 1.4, linecap: 'round' });
  g.circle(1.15 * s).center(-0.8 * s, -0.95 * s).fill(red).stroke({ color: '#b91616', width: 0.4 });
  g.circle(1.15 * s).center(0.9 * s, 0.65 * s).fill(red).stroke({ color: '#b91616', width: 0.4 });
  g.circle(1.05 * s).center(0, 0).fill(blue).stroke({ color: '#375391', width: 0.4 });
  g.circle(0.35 * s).center(-0.25 * s, -0.25 * s).fill({ color: '#fff', opacity: 0.35 }).stroke('none');
  g.move(x, y);
  g.rotate(rot || 0, x, y);
  addInteractivity(g, 'NO₂ molecule: one blue N atom and two red O atoms.', 'NO₂ molecule', 'Brown NO₂ is produced as N₂O₄ decomposes. Its concentration rises until the forward and reverse rates balance.');
  return g;
}

function drawN2O4(parent, x, y, s, rot) {
  var g = parent.group();
  g.line(-0.35 * s, 0, 0.35 * s, 0).stroke({ color: '#777', width: 1.5, linecap: 'round' });
  var coords = [
    [-0.45 * s, 0, -1.15 * s, -0.9 * s, -1.1 * s, 0.85 * s],
    [0.45 * s, 0, 1.15 * s, -0.85 * s, 1.12 * s, 0.9 * s]
  ];
  for (var i = 0; i < coords.length; i++) {
    var c = coords[i];
    g.line(c[0], c[1], c[2], c[3]).stroke({ color: '#777', width: 1.3, linecap: 'round' });
    g.line(c[0], c[1], c[4], c[5]).stroke({ color: '#777', width: 1.3, linecap: 'round' });
    g.circle(0.95 * s).center(c[0], c[1]).fill(blue).stroke({ color: '#375391', width: 0.4 });
    g.circle(1.05 * s).center(c[2], c[3]).fill(red).stroke({ color: '#b91616', width: 0.4 });
    g.circle(1.05 * s).center(c[4], c[5]).fill(red).stroke({ color: '#b91616', width: 0.4 });
  }
  g.circle(0.35 * s).center(-0.65 * s, -0.25 * s).fill({ color: '#fff', opacity: 0.35 }).stroke('none');
  g.move(x, y);
  g.rotate(rot || 0, x, y);
  addInteractivity(g, 'N₂O₄ molecule: two paired NO₂ units.', 'N₂O₄ molecule', 'N₂O₄ can split into two NO₂ molecules. At equilibrium it continues to split, but NO₂ molecules also recombine at the same rate.');
  return g;
}

function drawMolecules(parent, cx, cy, r, bigCount, smallCount) {
  var bigPos = [
    [-36, -28, -18], [-2, -35, 20], [34, -22, 42], [-39, 13, 16],
    [3, 7, -25], [40, 25, 10], [-5, 45, 35], [27, 0, -5], [-32, 39, 55]
  ];
  var smallPos = [
    [-48, -30, 8], [-20, -18, -30], [17, -38, 32], [48, -10, -10],
    [-47, 4, 42], [-19, 25, 18], [16, 18, -22], [47, 32, 28],
    [-30, 45, -35], [4, -6, 52], [31, -41, 14], [0, 42, -8],
