  ];
  for (var i = 0; i < Math.min(bigCount, bigPos.length); i++) {
    drawN2O4(parent, cx + bigPos[i][0], cy + bigPos[i][1], 8.6, bigPos[i][2]);
  }
  for (var j = 0; j < Math.min(smallCount, smallPos.length); j++) {
    drawNO2(parent, cx + smallPos[j][0], cy + smallPos[j][1], 7.4, smallPos[j][2]);
