}

function colorForProgress(p) {
  if (p <= 0.02) return { color: '#dfe2ff', opacity: 0.45 };
  if (p < 0.75) return { color: '#eac445', opacity: 0.72 };
  return { color: '#c86b2c', opacity: 0.82 };
}

function snapshotCounts(stageP) {
  var total = Math.round(8 + (initialA - 1) * 2.6);
  total = Math.max(5, Math.min(11, total));
  var big = Math.round(total * (1 - 0.68 * stageP));
  var small = Math.round(total * 1.35 * stageP);
  if (stageP === 0) small = 0;
  return { big: Math.max(0, big), small: Math.max(0, small) };
}

function drawTopPanel(root) {
  var xs = [110, 300, 490];
  var labels = ['t = 0', 'pre-equilibrium', 'at equilibrium'];
  var ps = [0, 0.58, 1];
  var selected = currentTime < 1.5 ? 0 : (currentTime < eqTime ? 1 : 2);

  formulaText(root, 'N₂O₄(g) ⇌ 2NO₂(g)', 300, 19, 18, 'middle');

  for (var i = 0; i < 3; i++) {
    haloText(root, labels[i], xs[i], 48, 22, 'middle');
    var col = colorForProgress(ps[i]);
    drawTestTube(root, xs[i] + 2, 105, col.color, col.opacity);
    drawArrow(root, xs[i], 141, 218);

    var rim = root.circle(136).center(xs[i], 294).fill('#f9f9f9').stroke({ color: gray, width: 4 });
    addInteractivity(rim, labels[i] + ': molecular mixture snapshot.', 'Container snapshot', 'The circles show molecular composition. The highlighted circle is the stage closest to the time marker on the graph.');
    if (i === selected) {
      root.circle(148).center(xs[i], 294).fill('none').stroke({ color: '#f2b632', width: 3, dasharray: '6,4' });
    }

    var c = snapshotCounts(ps[i]);
    drawMolecules(root, xs[i], 294, 68, c.big, c.small);
  }

  root.line(142, 365, 179, 390).stroke({ color: '#000', width: 3 });
  formulaText(root, 'N₂O₄', 206, 397, 22, 'middle');
  root.line(318, 360, 365, 392).stroke({ color: '#000', width: 3 });
  formulaText(root, 'NO₂', 394, 397, 22, 'middle');
  haloText(root, '(a)', 300, 442, 22, 'middle');
}

function graphX(t) {
  return 78 + (t / tMax) * 468;
}

function graphY(v, yMax) {
  return 790 - (v / yMax) * 235;
}

function makeCurvePath(fn, yMax) {
  var d = '';
  for (var i = 0; i <= 120; i++) {
    var t = (i / 120) * tMax;
    var x = graphX(t);
    var y = graphY(fn(t), yMax);
    d += (i === 0 ? 'M' : 'L') + x.toFixed(2) + ' ' + y.toFixed(2) + ' ';
  }
  return d;
}

function drawAxes(root, yLabel) {
  var gx0 = 78, gy0 = 790, gx1 = 552, gy1 = 535;
  root.line(gx0, gy0, gx1, gy0).stroke({ color: '#000', width: 2 });
  root.line(gx0, gy0, gx0, gy1).stroke({ color: '#000', width: 2 });
  root.polygon('552,790 532,782 532,798').fill('#000');
  root.polygon('78,535 70,557 86,557').fill('#000');
  root.line(graphX(0.48), 790, graphX(0.48), 810).stroke({ color: '#000', width: 2 });
  haloText(root, '0', graphX(0.48), 830, 21, 'middle');
  haloText(root, 'Time', 320, 830, 23, 'middle');
  var yt = haloText(root, yLabel, 48, 663, 23, 'middle');
  yt.rotate(-90, 48, 663);
}

function drawReadout(root) {
  var s = stateAt(currentTime);
  var x = 386, y = 472;
  var g = root.group();
  g.rect(194, 82).radius(7).move(x, y).fill({ color: '#fff', opacity: 0.92 }).stroke({ color: '#bbb', width: 1 });
  var lines = [
    'time = ' + currentTime.toFixed(1),
    '[N₂O₄] = ' + s.A.toFixed(2) + '    [NO₂] = ' + s.B.toFixed(2),
    'forward rate = ' + s.rf.toFixed(2),
    'reverse rate = ' + s.rr.toFixed(2)
  ];
  for (var i = 0; i < lines.length; i++) {
    g.text(lines[i]).font({ family: 'Arial, sans-serif', size: 13, anchor: 'start' }).fill('#111').move(x + 10, y + 8 + i * 18);
  }
  addInteractivity(g, 'Readout at the draggable time marker.', 'Linked quantities', 'The same time determines the molecular mixture, concentrations, and rates. Before equilibrium the forward and reverse rates differ; after equilibrium they are equal.');
}

function drawGraph(root) {
  var yLabel = graphMode === 'Rate' ? 'Rate' : 'Concentration';
  drawAxes(root, yLabel);

  var shadeX = graphX(eqTime);
  var shade = root.rect(graphX(tMax) - shadeX, 235).move(shadeX, 555).fill({ color: paleYellow, opacity: 0.92 }).stroke('none');
  addInteractivity(shade, 'After this dashed line, equilibrium has been achieved.', 'Equilibrium region', 'In this region concentrations stay constant. The reaction has not stopped: the forward and reverse rates are equal.');

  root.line(shadeX, 545, shadeX, 790).stroke({ color: '#000', width: 1.8, dasharray: '10,9' });

  var sNow = stateAt(currentTime);
  var yMax;
  if (graphMode === 'Concentration') {
    yMax = Math.max(initialA, sNow.bEq) * 1.17;
    var cBlue = root.path(makeCurvePath(function (t) { return stateAt(t).A; }, yMax))
      .fill('none').stroke({ color: blue, width: 5, linecap: 'round', linejoin: 'round' });
    var cRed = root.path(makeCurvePath(function (t) { return stateAt(t).B; }, yMax))
      .fill('none').stroke({ color: redOrange, width: 5, linecap: 'round', linejoin: 'round' });
    addInteractivity(cBlue, '[N₂O₄] decreases then becomes constant.', 'N₂O₄ concentration', 'N₂O₄ is consumed while NO₂ forms. Once equilibrium is reached, its concentration plateaus.');
    addInteractivity(cRed, '[NO₂] increases then becomes constant.', 'NO₂ concentration', 'NO₂ builds up from nearly zero. Its concentration stops changing when the reverse reaction catches up to the forward reaction.');
    formulaText(root, 'NO₂', 245, graphY(stateAt(2.8).B, yMax) - 34, 23, 'middle');
    formulaText(root, 'N₂O₄', 250, graphY(stateAt(3.3).A, yMax) + 38, 23, 'middle');
    haloText(root, 'Equilibrium\nachieved', 430, 640, 22, 'middle');
    haloText(root, '(b)', 300, 867, 22, 'middle');
  } else {
    yMax = Math.max(1.0 * initialA, sNow.rEq) * 1.15;
    var rBlue = root.path(makeCurvePath(function (t) { return stateAt(t).rf; }, yMax))
      .fill('none').stroke({ color: blue, width: 5, linecap: 'round', linejoin: 'round' });
    var rRed = root.path(makeCurvePath(function (t) { return stateAt(t).rr; }, yMax))
      .fill('none').stroke({ color: redOrange, width: 5, linecap: 'round', linejoin: 'round' });
    addInteractivity(rBlue, 'Forward rate kf[N₂O₄] decreases as N₂O₄ is used.', 'Forward rate', 'The forward decomposition rate is initially high because N₂O₄ is abundant. It falls until it equals the reverse rate.');
    addInteractivity(rRed, 'Reverse rate kr[NO₂]² increases as NO₂ accumulates.', 'Reverse rate', 'The reverse association rate begins near zero because little NO₂ is present. It rises until it equals the forward rate.');
    formulaText(root, 'k_f[N₂O₄]', 165, graphY(stateAt(1.2).rf, yMax) - 8, 20, 'middle');
    formulaText(root, 'k_r[NO₂]²', 170, graphY(stateAt(1.8).rr, yMax) + 42, 20, 'middle');
    haloText(root, 'Equilibrium\nachieved', 430, 700, 22, 'middle');
    haloText(root, '(c)', 300, 867, 22, 'middle');
  }

  var mx = graphX(currentTime);
  var marker = root.line(mx, 535, mx, 800).stroke({ color: '#111', width: 2.2 });
  var handle = root.circle(16).center(mx, 790).fill('#fff').stroke({ color: '#111', width: 2 });
  var knob = root.polygon((mx - 8) + ',806 ' + (mx + 8) + ',806 ' + mx + ',819').fill('#111');
  addInteractivity(marker, 'Drag to inspect time = ' + currentTime.toFixed(1), 'Time marker', 'The vertical marker links a graph position to the molecular picture and readouts.');
  addInteractivity(handle, 'Drag the handle along the time axis.', 'Time marker', 'Move the marker before and after the dashed line to compare changing concentrations with the equilibrium plateau.');
  addInteractivity(knob, 'Drag the handle along the time axis.', 'Time marker', 'Move the marker before and after the dashed line to compare changing concentrations with the equilibrium plateau.');

  function startDrag(e) {
    draggingMarker = true;
    e.preventDefault();
    hideTooltip();
  }
  marker.on('mousedown', startDrag);
  handle.on('mousedown', startDrag);
  knob.on('mousedown', startDrag);

