// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 600;
var layoutMode = 'Source layout: both graphs';
var dynamicOn = false;
var animPhase = 0;
var activeStep = 0;
var animTimer = null;

var blue = '#4f67b1';
var red = '#ed1c24';
var orangeRed = '#c54b2f';
var rimGray = '#7f8084';
var paleYellow = '#f5edcf';

var demoSteps = [
  {
    title: 'Read the source layout',
    narration: 'The default view keeps the molecular snapshots, concentration graph, and rate graph visible at the same time. The lower two panels show the same equilibrium moment from two perspectives: concentrations become constant when the two rates become equal.',
    state: { graphLayout: 'Source layout: both graphs' }
  },
  {
    title: 'Focus on concentration change',
    narration: 'In the concentration graph, [N₂O₄] falls while [NO₂] rises as the mixture turns more orange-brown. Once equilibrium is achieved, both curves flatten rather than continuing to change.',
    state: { graphLayout: 'Focus: concentration graph' }
  },
  {
    title: 'Focus on the rate condition',
