    state: { graphLayout: 'Focus: rate graph' }
  },
  {
    title: 'Return to the complete explanation',
    narration: 'Returning to the source layout connects all three panels: molecule counts, graph plateaus, and equal rates describe the same dynamic equilibrium.',
    state: { graphLayout: 'Source layout: both graphs' }
  }
];

function addInteractivity(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
  return el;
}

function haloText(parent, txt, x, y, size, anchor) {
  var t = parent.text(txt).font({ family: 'Arial, sans-serif', size: size, anchor: anchor || 'middle' }).fill('#000');
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  t.center(x, y);
  return t;
}

function multiText(parent, lines, x, y, size) {
  var t = parent.text(function (add) {
    for (var i = 0; i < lines.length; i++) {
      var sp = add.tspan(lines[i]);
      if (i < lines.length - 1) sp.newLine();
    }
  }).font({ family: 'Arial, sans-serif', size: size, anchor: 'middle', leading: '1.15em' }).fill('#000');
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  t.center(x, y);
  return t;
}

function drawTestTube(parent, cx, cy, fill, opacity, rot) {
  var g = parent.group();
  var tube = g.rect(24, 122).radius(12).center(0, 0)
    .fill({ color: fill, opacity: opacity })
    .stroke({ color: '#c9c9d7', width: 1.4 });
  g.line(-6, -48, -6, 43).stroke({ color: '#fff', width: 4, opacity: 0.35, linecap: 'round' });
  g.ellipse(24, 10).center(0, 61).fill({ color: fill, opacity: opacity }).stroke({ color: '#c9c9d7', width: 0.8 });
  g.attr({ transform: 'translate(' + cx + ' ' + cy + ') rotate(' + (rot || -32) + ')' });
  addInteractivity(tube, 'Gas color deepens as more brown NO₂ is present.', 'Color cue', 'N₂O₄ is nearly colorless, while NO₂ is brown. The test tubes give a macroscopic color cue for the molecular composition below.');
  return g;
}

function drawOutlinedCurvedArrow(parent, x, y) {
  var p = 'M ' + (x - 13) + ' ' + y + ' C ' + (x - 44) + ' ' + (y + 25) + ' ' + (x - 37) + ' ' + (y + 57) + ' ' + (x - 16) + ' ' + (y + 72);
  parent.path(p).fill('none').stroke({ color: '#111', width: 23, linecap: 'round', linejoin: 'round' });
  parent.path(p).fill('none').stroke({ color: '#fff', width: 21, linecap: 'round', linejoin: 'round' });
  var head = parent.polygon((x - 33) + ',' + (y + 62) + ' ' + (x + 2) + ',' + (y + 63) + ' ' + (x - 18) + ',' + (y + 100))
    .fill('#fff').stroke({ color: '#111', width: 1.2, linejoin: 'round' });
  addInteractivity(head, 'The gas sample is represented at the molecular level below.', 'Snapshot arrow', 'Each arrow connects the visible gas color in a tube to a particle-level snapshot of the same reacting system.');
}

function moleculeTransform(g, x, y, rot) {
  g.attr({ transform: 'translate(' + x + ' ' + y + ') rotate(' + (rot || 0) + ')' });
  return g;
}

function drawNO2(parent, x, y, s, rot, op) {
  var g = parent.group().opacity(op == null ? 1 : op);
  g.line(0, 0, -0.9 * s, -0.75 * s).stroke({ color: '#6d6d6d', width: 1.5, linecap: 'round' });
  g.line(0, 0, 0.95 * s, 0.65 * s).stroke({ color: '#6d6d6d', width: 1.5, linecap: 'round' });
  g.circle(1.16 * s).center(-0.9 * s, -0.75 * s).fill(red).stroke({ color: '#b91616', width: 0.35 });
  g.circle(1.16 * s).center(0.95 * s, 0.65 * s).fill(red).stroke({ color: '#b91616', width: 0.35 });
  g.circle(1.08 * s).center(0, 0).fill(blue).stroke({ color: '#314b91', width: 0.35 });
  g.circle(0.35 * s).center(-0.24 * s, -0.25 * s).fill({ color: '#fff', opacity: 0.35 }).stroke('none');
  moleculeTransform(g, x, y, rot);
  addInteractivity(g, 'NO₂: one nitrogen atom with two oxygen atoms.', 'NO₂ molecule', 'Brown NO₂ forms as N₂O₄ decomposes. Its concentration rises until the reverse reaction balances the forward reaction.');
  return g;
}

function drawN2O4(parent, x, y, s, rot, op) {
  var g = parent.group().opacity(op == null ? 1 : op);
  g.line(-0.43 * s, 0, 0.43 * s, 0).stroke({ color: '#6d6d6d', width: 1.7, linecap: 'round' });
  var sides = [
    [-0.48 * s, 0, -1.18 * s, -0.82 * s, -1.15 * s, 0.86 * s],
    [0.48 * s, 0, 1.18 * s, -0.82 * s, 1.15 * s, 0.86 * s]
  ];
  for (var i = 0; i < sides.length; i++) {
    var c = sides[i];
    g.line(c[0], c[1], c[2], c[3]).stroke({ color: '#6d6d6d', width: 1.45, linecap: 'round' });
    g.line(c[0], c[1], c[4], c[5]).stroke({ color: '#6d6d6d', width: 1.45, linecap: 'round' });
    g.circle(1.03 * s).center(c[0], c[1]).fill(blue).stroke({ color: '#314b91', width: 0.35 });
    g.circle(1.13 * s).center(c[2], c[3]).fill(red).stroke({ color: '#b91616', width: 0.35 });
    g.circle(1.13 * s).center(c[4], c[5]).fill(red).stroke({ color: '#b91616', width: 0.35 });
  }
  g.circle(0.36 * s).center(-0.68 * s, -0.22 * s).fill({ color: '#fff', opacity: 0.35 }).stroke('none');
  moleculeTransform(g, x, y, rot);
  addInteractivity(g, 'N₂O₄: two linked NO₂ units.', 'N₂O₄ molecule', 'N₂O₄ can split into two NO₂ molecules. At equilibrium it still splits, but NO₂ molecules recombine at the same rate.');
  return g;
}

function drawMoleculeSet(parent, cx, cy, stage) {
  var n2o4Sets = [
    [[-38, -31, -18], [6, -45, 10], [40, -28, 35], [-44, 8, 18], [-6, 2, -28], [42, 22, -8], [-4, 43, 28]],
    [[-43, -16, 22], [9, -35, -24], [38, 28, 10], [-16, 30, 40]],
    [[-42, -22, 16], [-2, -34, -18], [36, 15, 12], [-15, 38, 34]]
  ];
  var no2Sets = [
    [],
    [[-55, 27, 18], [-37, -43, 42], [-20, 3, -20], [15, -5, 30], [47, -20, -18], [54, 21, 36], [-2, 47, -28], [27, 44, 8], [-49, -5, -42], [18, -45, 12]],
    [[-53, -18, 8], [-42, 22, 44], [-17, -5, -18], [9, 17, 22], [36, -31, -32], [53, 3, 15], [41, 38, -12], [-8, 49, 38], [20, -47, 28], [-31, -43, -8]]
  ];
  for (var i = 0; i < n2o4Sets[stage].length; i++) {
    var a = n2o4Sets[stage][i];
    drawN2O4(parent, cx + a[0], cy + a[1], 9.0, a[2]);
  }
  for (var j = 0; j < no2Sets[stage].length; j++) {
    var b = no2Sets[stage][j];
    drawNO2(parent, cx + b[0], cy + b[1], 7.8, b[2]);
  }
  if (dynamicOn && stage === 2) drawDynamicGlyph(parent, cx, cy);
}

function drawDynamicGlyph(parent, cx, cy) {
  var op = animPhase ? 0.72 : 0.25;
  var g = parent.group().opacity(op);
  g.path('M ' + (cx - 32) + ' ' + (cy - 3) + ' C ' + (cx - 8) + ' ' + (cy - 28) + ' ' + (cx + 21) + ' ' + (cy - 25) + ' ' + (cx + 39) + ' ' + (cy - 3))
    .fill('none').stroke({ color: '#555', width: 2.1, linecap: 'round' });
  g.polygon((cx + 39) + ',' + (cy - 3) + ' ' + (cx + 28) + ',' + (cy - 8) + ' ' + (cx + 33) + ',' + (cy + 3)).fill('#555');
  g.path('M ' + (cx + 35) + ' ' + (cy + 20) + ' C ' + (cx + 5) + ' ' + (cy + 43) + ' ' + (cx - 22) + ' ' + (cy + 37) + ' ' + (cx - 40) + ' ' + (cy + 13))
    .fill('none').stroke({ color: '#555', width: 2.1, linecap: 'round' });
  g.polygon((cx - 40) + ',' + (cy + 13) + ' ' + (cx - 29) + ',' + (cy + 18) + ' ' + (cx - 34) + ',' + (cy + 7)).fill('#555');
  addInteractivity(g, 'Molecules continue to interconvert at equilibrium.', 'Dynamic equilibrium', 'The overall numbers remain steady because N₂O₄ splitting and NO₂ recombining occur at equal rates.');
}

function drawTopPanel(parent) {
  var xs = [105, 300, 495];
  var labels = ['t = 0', 'pre-equilibrium', 'at equilibrium'];
  var tubeColors = ['#dfe2ff', '#f1c94b', '#df7b35'];
  var tubeOps = [0.45, 0.72, 0.85];

  haloText(parent, 'N₂O₄(g) ⇌ 2NO₂(g)', 300, 44, 12, 'middle');
  for (var i = 0; i < 3; i++) {
    haloText(parent, labels[i], xs[i], 24, 22, 'middle');
    drawTestTube(parent, xs[i], 98, tubeColors[i], tubeOps[i], -32);
    drawOutlinedCurvedArrow(parent, xs[i] + 1, 117);
    var rim = parent.circle(144).center(xs[i], 274).fill('#fbfbfb').stroke({ color: rimGray, width: 4 });
    addInteractivity(rim, labels[i] + ': sealed molecular snapshot.', 'Molecular snapshot', 'The circular containers compare the same reaction mixture at different times as it approaches equilibrium.');
    drawMoleculeSet(parent, xs[i], 274, i);
  }

  parent.line(113, 337, 176, 376).stroke({ color: '#000', width: 3.2, linecap: 'round' });
  haloText(parent, 'N₂O₄', 207, 386, 24, 'middle');
  parent.line(302, 339, 366, 377).stroke({ color: '#000', width: 3.2, linecap: 'round' });
  haloText(parent, 'NO₂', 397, 386, 24, 'middle');
  haloText(parent, '(a)', 300, 432, 23, 'middle');
}

function graphMap(cfg, t, v, ymax) {
  return {
    x: cfg.x0 + (t / cfg.tMax) * cfg.w,
    y: cfg.y0 - (v / ymax) * cfg.h
  };
}

function curvePath(cfg, fn, ymax) {
  var d = '';
  for (var i = 0; i <= 160; i++) {
    var t = (i / 160) * cfg.tMax;
    var p = graphMap(cfg, t, fn(t), ymax);
    d += (i === 0 ? 'M ' : 'L ') + p.x.toFixed(2) + ' ' + p.y.toFixed(2) + ' ';
  }
  return d;
}

function progress(t, eqT) {
  if (t >= eqT) return 1;
  var tau = 1.28;
  var s = 1 - Math.exp(-t / tau);
  var e = 1 - Math.exp(-eqT / tau);
  return s / e;
}

function concA(t, eqT) {
  var p = progress(t, eqT);
  return t >= eqT ? 0.35 : 0.35 + (0.82 - 0.35) * Math.pow(1 - p, 1.55);
}

function concB(t, eqT) {
  var p = progress(t, eqT);
  return t >= eqT ? 0.84 : 0.84 * (1 - Math.pow(1 - p, 1.65));
}

function rateF(t, eqT) {
  var p = progress(t, eqT);
  return t >= eqT ? 0.58 : 0.58 + (0.92 - 0.58) * Math.pow(1 - p, 1.7);
}

function rateR(t, eqT) {
  var p = progress(t, eqT);
  return t >= eqT ? 0.58 : 0.58 * (1 - Math.pow(1 - p, 2.2));
}

function drawAxes(parent, cfg, yLabel) {
  parent.line(cfg.x0, cfg.y0, cfg.x0 + cfg.w + 36, cfg.y0).stroke({ color: '#000', width: 2 });
  parent.line(cfg.x0, cfg.y0, cfg.x0, cfg.y0 - cfg.h - 36).stroke({ color: '#000', width: 2 });
  parent.polygon((cfg.x0 + cfg.w + 36) + ',' + cfg.y0 + ' ' + (cfg.x0 + cfg.w + 14) + ',' + (cfg.y0 - 8) + ' ' + (cfg.x0 + cfg.w + 14) + ',' + (cfg.y0 + 8)).fill('#000');
  parent.polygon(cfg.x0 + ',' + (cfg.y0 - cfg.h - 36) + ' ' + (cfg.x0 - 8) + ',' + (cfg.y0 - cfg.h - 14) + ' ' + (cfg.x0 + 8) + ',' + (cfg.y0 - cfg.h - 14)).fill('#000');
  parent.line(cfg.x0, cfg.y0, cfg.x0, cfg.y0 + 18).stroke({ color: '#000', width: 2 });
  haloText(parent, '0', cfg.x0, cfg.y0 + 38, 22, 'middle');
  haloText(parent, 'Time', cfg.x0 + cfg.w / 2, cfg.y0 + 38, 24, 'middle');
  var yt = haloText(parent, yLabel, cfg.x0 - 34, cfg.y0 - cfg.h / 2, 24, 'middle');
  yt.rotate(-90, cfg.x0 - 34, cfg.y0 - cfg.h / 2);
}

function drawGraph(parent, type, cfg, panelLabel) {
  var eqT = 5, ymax = 1.0;
