function graphMap(cfg, t, v, ymax) {
  return {
    x: cfg.x0 + (t / cfg.tMax) * cfg.w,
    y: cfg.y0 - (v / ymax) * cfg.h
  };
}

function curvePath(cfg, fn, ymax) {
  var d = '';
  for (var i = 0; i <= 160; i++) {
    var t = (i / 160) * cfg.tMax;
    var p = graphMap(cfg, t, fn(t), ymax);
    d += (i === 0 ? 'M ' : 'L ') + p.x.toFixed(2) + ' ' + p.y.toFixed(2) + ' ';
  }
  return d;
}

function progress(t, eqT) {
  if (t >= eqT) return 1;
  var tau = 1.28;
  var s = 1 - Math.exp(-t / tau);
  var e = 1 - Math.exp(-eqT / tau);
  return s / e;
}

function concA(t, eqT) {
  var p = progress(t, eqT);
  return t >= eqT ? 0.35 : 0.35 + (0.82 - 0.35) * Math.pow(1 - p, 1.55);
}

function concB(t, eqT) {
  var p = progress(t, eqT);
  return t >= eqT ? 0.84 : 0.84 * (1 - Math.pow(1 - p, 1.65));
}

function rateF(t, eqT) {
  var p = progress(t, eqT);
  return t >= eqT ? 0.58 : 0.58 + (0.92 - 0.58) * Math.pow(1 - p, 1.7);
}

function rateR(t, eqT) {
  var p = progress(t, eqT);
  return t >= eqT ? 0.58 : 0.58 * (1 - Math.pow(1 - p, 2.2));
}

