    addInteractivity(r1, 'Forward rate decreases as N₂O₄ is used.', 'Forward rate', 'The forward decomposition rate is high at first because N₂O₄ is abundant, then it falls until it equals the reverse rate.');
    addInteractivity(r2, 'Reverse rate increases as NO₂ accumulates.', 'Reverse rate', 'The reverse association rate starts near zero because little NO₂ is present, then rises until it equals the forward rate.');
    var pf = graphMap(cfg, 1.15, rateF(1.15, eqT), ymax);
