function addInteractivity(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
  return el;
}

function haloText(parent, txt, x, y, size, anchor) {
  var t = parent.text(txt)
    .font({ family: 'Arial, Helvetica, sans-serif', size: size, anchor: anchor || 'middle' })
    .fill('#000');
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': Math.max(2.5, size * 0.16), 'stroke-linejoin': 'round' });
  if ((anchor || 'middle') === 'middle') t.center(x, y);
  else t.move(x, y - size * 0.55);
  return t;
}

function multiLine(parent, lines, x, y, size, gap) {
  var g = parent.group();
  gap = gap || size * 1.16;
  var start = y - gap * (lines.length - 1) / 2;
  for (var i = 0; i < lines.length; i++) haloText(g, lines[i], x, start + i * gap, size, 'middle');
