function graphMap(cfg, t, v, ymax) {
  return {
    x: cfg.x0 + (t / cfg.tMax) * cfg.w,
    y: cfg.y0 - (v / ymax) * cfg.h
  };
}

function curvePath(cfg, fn, ymax) {
  var d = '';
  for (var i = 0; i <= 180; i++) {
    var t = (i / 180) * cfg.tMax;
    var p = graphMap(cfg, t, fn(t), ymax);
    d += (i === 0 ? 'M ' : 'L ') + p.x.toFixed(2) + ' ' + p.y.toFixed(2) + ' ';
  }
  return d;
}

function progress(t, eqT) {
  if (t >= eqT) return 1;
  var tau = 1.26;
  var s = 1 - Math.exp(-t / tau);
  var e = 1 - Math.exp(-eqT / tau);
  return s / e;
}

function concA(t, eqT) {
  var p = progress(t, eqT);
  return t >= eqT ? 0.40 : 0.40 + (0.79 - 0.40) * Math.pow(1 - p, 1.58);
}

function concB(t, eqT) {
  var p = progress(t, eqT);
  return t >= eqT ? 0.84 : 0.84 * (1 - Math.pow(1 - p, 1.62));
}

function rateF(t, eqT) {
  var p = progress(t, eqT);
  return t >= eqT ? 0.58 : 0.58 + (0.89 - 0.58) * Math.pow(1 - p, 1.62);
}

function rateR(t, eqT) {
  var p = progress(t, eqT);
  return t >= eqT ? 0.58 : 0.58 * (1 - Math.pow(1 - p, 2.05));
}

function drawAxes(parent, cfg, yLabel) {
  parent.line(cfg.x0, cfg.y0, cfg.x0 + cfg.w + 34, cfg.y0).stroke({ color: '#000', width: 2 });
  parent.line(cfg.x0, cfg.y0, cfg.x0, cfg.y0 - cfg.h - 34).stroke({ color: '#000', width: 2 });
  parent.polygon((cfg.x0 + cfg.w + 34) + ',' + cfg.y0 + ' ' + (cfg.x0 + cfg.w + 12) + ',' + (cfg.y0 - 8) + ' ' + (cfg.x0 + cfg.w + 12) + ',' + (cfg.y0 + 8)).fill('#000');
  parent.polygon(cfg.x0 + ',' + (cfg.y0 - cfg.h - 34) + ' ' + (cfg.x0 - 8) + ',' + (cfg.y0 - cfg.h - 12) + ' ' + (cfg.x0 + 8) + ',' + (cfg.y0 - cfg.h - 12)).fill('#000');
  parent.line(cfg.x0, cfg.y0, cfg.x0, cfg.y0 + 17).stroke({ color: '#000', width: 2 });
  haloText(parent, '0', cfg.x0, cfg.y0 + 37, 20, 'middle');
  haloText(parent, 'Time', cfg.x0 + cfg.w / 2, cfg.y0 + 37, 22, 'middle');
  var yt = haloText(parent, yLabel, cfg.x0 - 35, cfg.y0 - cfg.h / 2, 22, 'middle');
  yt.rotate(-90, cfg.x0 - 35, cfg.y0 - cfg.h / 2);
}

function drawGraph(parent, type, cfg, panelLabel) {
  var eqT = 5, ymax = 1.0;
  var eqX = graphMap(cfg, eqT, 0, ymax).x;
  var shade = parent.rect(cfg.x0 + cfg.w - eqX, cfg.h).move(eqX, cfg.y0 - cfg.h).fill({ color: paleYellow, opacity: 0.95 }).stroke('none');
  addInteractivity(shade, 'Equilibrium region: macroscopic values are constant here.', 'Equilibrium achieved', 'After the dashed line, concentrations do not change because the forward and reverse reaction rates are equal.');
  drawAxes(parent, cfg, type === 'conc' ? 'Concentration' : 'Rate');
  parent.line(eqX, cfg.y0 - cfg.h - 5, eqX, cfg.y0).stroke({ color: '#000', width: 1.6, dasharray: '9,8' });

  if (type === 'conc') {
    var c1 = parent.path(curvePath(cfg, function (t) { return concA(t, eqT); }, ymax))
      .fill('none').stroke({ color: blue, width: 4.6, linecap: 'butt', linejoin: 'round' });
    var c2 = parent.path(curvePath(cfg, function (t) { return concB(t, eqT); }, ymax))
      .fill('none').stroke({ color: orangeRed, width: 4.6, linecap: 'butt', linejoin: 'round' });
    addInteractivity(c1, '[N₂O₄] decreases and then becomes constant.', 'N₂O₄ concentration', 'N₂O₄ is consumed as NO₂ forms. At equilibrium its concentration plateaus rather than dropping to zero.');
    addInteractivity(c2, '[NO₂] increases and then becomes constant.', 'NO₂ concentration', 'NO₂ builds up from almost none, then remains constant once the opposing rates become equal.');
    var pNO2 = graphMap(cfg, 3.15, concB(3.15, eqT), ymax);
    var pN2O4 = graphMap(cfg, 3.18, concA(3.18, eqT), ymax);
    haloText(parent, '[NO₂]', pNO2.x + 31, pNO2.y - 18, 20, 'middle');
    haloText(parent, '[N₂O₄]', pN2O4.x + 31, pN2O4.y + 34, 20, 'middle');
    multiLine(parent, ['Equilibrium', 'achieved'], eqX + (cfg.x0 + cfg.w - eqX) / 2, cfg.y0 - cfg.h * 0.60, 21, 25);
  } else {
    var r1 = parent.path(curvePath(cfg, function (t) { return rateF(t, eqT); }, ymax))
      .fill('none').stroke({ color: blue, width: 4.6, linecap: 'butt', linejoin: 'round' });
    var r2 = parent.path(curvePath(cfg, function (t) { return rateR(t, eqT); }, ymax))
      .fill('none').stroke({ color: orangeRed, width: 4.6, linecap: 'butt', linejoin: 'round' });
    addInteractivity(r1, 'Forward rate decreases as N₂O₄ is used.', 'Forward rate', 'The forward decomposition rate is high at first because N₂O₄ is abundant, then it falls until it equals the reverse rate.');
    addInteractivity(r2, 'Reverse rate increases as NO₂ accumulates.', 'Reverse rate', 'The reverse association rate starts near zero because little NO₂ is present, then rises until it equals the forward rate.');
    var pf = graphMap(cfg, 1.07, rateF(1.07, eqT), ymax);
    var pr = graphMap(cfg, 1.10, rateR(1.10, eqT), ymax);
    haloText(parent, 'k_f[N₂O₄]', pf.x + 58, pf.y - 8, 20, 'middle');
    haloText(parent, 'k_r[NO₂]²', pr.x + 58, pr.y + 35, 20, 'middle');
    multiLine(parent, ['Equilibrium', 'achieved'], eqX + (cfg.x0 + cfg.w - eqX) / 2, cfg.y0 - cfg.h * 0.37, 21, 25);
  }
  haloText(parent, panelLabel, 300, cfg.y0 + 82, 22, 'middle');
}

function render() {
  draw.clear();
  if (layoutMode === 'Source layout: both graphs') {
    draw.viewbox(0, 0, 600, 950);
    var root = draw.group();
    drawTopPanel(root);
    drawGraph(root, 'conc', { x0: 88, y0: 590, w: 438, h: 170, tMax: 10 }, '(b)');
    drawGraph(root, 'rate', { x0: 88, y0: 870, w: 438, h: 170, tMax: 10 }, '(c)');
  } else if (layoutMode === 'Focus: concentration graph') {
    draw.viewbox(0, 0, 600, 765);
    var concRoot = draw.group();
    drawTopPanel(concRoot);
    drawGraph(concRoot, 'conc', { x0: 88, y0: 675, w: 438, h: 250, tMax: 10 }, '(b)');
  } else {
    draw.viewbox(0, 0, 600, 765);
    var rateRoot = draw.group();
    drawTopPanel(rateRoot);
    drawGraph(rateRoot, 'rate', { x0: 88, y0: 675, w: 438, h: 250, tMax: 10 }, '(c)');
  }
}

function update_graphLayout(v) {
  layoutMode = v;
  render();
}

function toggle_dynamicMolecules(on) {
  dynamicOn = on;
  if (animTimer) {
    clearInterval(animTimer);
    animTimer = null;
  }
  if (dynamicOn) {
    animTimer = setInterval(function () {
      animPhase = 1 - animPhase;
      render();
    }, 650);
  }
  render();
}

function applyStep(i) {
  activeStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[activeStep];
  layoutMode = step.state.graphLayout;

  var sel = document.getElementById('graphLayoutInput');
  var narration = document.getElementById('demoNarration');
  var stepLabel = document.getElementById('stepLabel');

  if (sel) sel.value = layoutMode;
  if (narration) narration.textContent = step.narration;
  if (stepLabel) stepLabel.textContent = (activeStep + 1) + '/' + demoSteps.length + ' ' + step.title;

  render();
}

function nextStep() {
  applyStep((activeStep + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((activeStep - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

